<?php
declare(strict_types=1);
require_once __DIR__.'/project-settings-model.php';
require_once __DIR__.'/contract-model.php';
require_once __DIR__.'/admin-shell.php';

$user=(string)(getenv('ADMIN_USERNAME')?:''); $password=(string)(getenv('ADMIN_PASSWORD')?:'');
if($user===''||$password===''||!isset($_SERVER['PHP_AUTH_USER'],$_SERVER['PHP_AUTH_PW'])||!hash_equals($user,(string)$_SERVER['PHP_AUTH_USER'])||!hash_equals($password,(string)$_SERVER['PHP_AUTH_PW'])) { header('WWW-Authenticate: Basic realm="Grzywniak Admin"'); http_response_code(401); exit('Authentication required.'); }
header('Content-Type: text/html; charset=utf-8');
header('Cache-Control: no-store');
header('X-Content-Type-Options: nosniff');
$csrf=contractToken(); $error=''; $saved=false;
if($_SERVER['REQUEST_METHOD']==='POST') {
    if(!hash_equals($csrf,(string)($_POST['csrf']??''))) { http_response_code(403); $error='Sesja formularza wygasła. Odśwież stronę.'; }
    else {
        try { projectSettingsSave($_POST); header('Location: '.apiPath('project-settings.php').'?saved=1',true,303); exit; }
        catch(Throwable $exception) { http_response_code(422); $error=$exception instanceof InvalidArgumentException?$exception->getMessage():'Nie udało się zapisać ustawień. Sprawdź uprawnienia katalogu danych i spróbuj ponownie.'; }
    }
}
$saved=isset($_GET['saved']);
function settingsEsc(mixed $value): string { return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
$schema=projectSettingsSchema();
$total=0; $configured=0;
foreach(projectSettingsFields() as $name=>$field) { $total++; if(projectSettingConfigured($name)) $configured++; }
ob_start(static fn(string $html):string=>adminShellPage($html,'settings'));
