:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#080b13;color:#ecf0fc;font:14px/1.5 system-ui,sans-serif}a{color:inherit}button,input,textarea{font:inherit}main{max-width:1230px;margin:auto;padding:28px 22px 70px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:30px}.brand{font-weight:800;letter-spacing:-.02em}.links{display:flex;gap:8px;flex-wrap:wrap}.links a{padding:8px 12px;border:1px solid #303a52;border-radius:9px;text-decoration:none;color:#c5d0e8}.links a:hover{border-color:#7586ff;color:#fff}.eyebrow{color:#8da1fa;text-transform:uppercase;letter-spacing:.15em;font-size:11px;font-weight:700}h1{font-size:clamp(29px,4vw,42px);letter-spacing:-.04em;margin:7px 0}h2{font-size:20px;margin:0}p{margin:0}.intro{max-width:760px;color:#a6b2cb}.summary{display:flex;align-items:center;gap:20px;flex-wrap:wrap;padding:19px 22px;margin:25px 0;border:1px solid #33426d;border-radius:16px;background:linear-gradient(120deg,#182343,#101722)}.summary b{font-size:28px}.summary span{color:#b8c5e0}.summary small{display:block;color:#8f9bb5}.layout{display:grid;grid-template-columns:210px minmax(0,1fr);gap:24px;align-items:start}.side{position:sticky;top:22px;display:grid;gap:6px}.side a{display:block;border-radius:9px;padding:10px 12px;color:#aebbd2;text-decoration:none}.side a:hover,.side a:focus-visible{background:#1a2440;color:#fff}.content{display:grid;gap:18px}.card{border:1px solid #273249;border-radius:17px;background:#111723;padding:24px;scroll-margin-top:20px}.cardhead{display:flex;justify-content:space-between;gap:12px;align-items:start;margin-bottom:21px}.cardhead p{color:#98a9c5;margin-top:5px;max-width:650px}.tag{border:1px solid #38486e;border-radius:999px;padding:5px 9px;color:#9fb4ed;font-size:11px;white-space:nowrap}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.field.wide{grid-column:1/-1}.field label{display:block;font-weight:650;margin-bottom:6px}.hint{display:block;color:#8e9cba;font-size:12px;margin-bottom:7px}.field input,.field textarea{width:100%;padding:10px 12px;border:1px solid #34415a;border-radius:9px;background:#0b111c;color:#edf2ff;outline:none}.field input:focus,.field textarea:focus{border-color:#8997ff;box-shadow:0 0 0 3px #8997ff22}.field textarea{min-height:125px;resize:vertical}.secretstate{font-size:11px;color:#7ee3b2;margin-left:7px}.empty{color:#94a1ba}.notice{border:1px solid #326652;background:#143326;color:#b1f2d0;padding:13px 15px;border-radius:10px;margin:17px 0}.notice.error{border-color:#7c3f4a;background:#311a22;color:#ffb8c3}.footer{position:sticky;bottom:0;padding:15px 0;background:linear-gradient(transparent,#080b13 18%);text-align:right}.save{border:0;border-radius:10px;background:#7286ff;color:#080c19;padding:12px 20px;font-weight:800;cursor:pointer}.save:hover{background:#94a2ff}.security{font-size:12px;color:#8998b4;margin-top:12px}@media(max-width:760px){main{padding:20px 14px 60px}.top{align-items:start;flex-direction:column}.layout{display:block}.side{position:static;display:flex;overflow:auto;margin-bottom:14px}.side a{white-space:nowrap}.grid{grid-template-columns:1fr}.card{padding:19px}.cardhead{display:block}.tag{display:inline-block;margin-top:8px}}
</style></head><body><main><header class="top"><div class="brand">Grzywniak <span style="color:#7e8ba9">/ Admin</span></div><nav class="links"><a href="/api/admin.php">Panel briefów</a><a href="/api/project-portfolio.php">Centrum projektów</a></nav></header><span class="eyebrow">Konfiguracja systemu</span><h1>Ustawienia centrum projektów</h1><p class="intro">Połączenia z usługami, środowisko agentów i limity w jednym miejscu. Zapisane sekrety nie są ponownie wyświetlane. Dostęp agentów do GitHuba konfigurujesz na ich osobnym koncie Codex.</p><p style="margin-top:15px"><a href="/api/project-template-catalog.php" style="color:#b6c8ff">Zobacz katalog i propozycje szablonów →</a></p><div class="summary"><b><?= $configured ?>/<?= $total ?></b><span>pól skonfigurowanych<small>W tym wartości zapisane na serwerze i ustawione przez środowisko</small></span></div><?php if($saved):?><div class="notice" role="status">Ustawienia zostały zapisane. Worker odczyta je przy następnym zadaniu.</div><?php endif?><?php if($error!==''):?><div class="notice error" role="alert"><?=settingsEsc($error)?></div><?php endif?><div class="layout"><nav class="side" aria-label="Sekcje ustawień"><?php foreach($schema as $id=>$section):?><a href="#<?=settingsEsc($id)?>"><?=settingsEsc($section['title'])?></a><?php endforeach?></nav><form class="content" method="post" autocomplete="off"><input type="hidden" name="csrf" value="<?=settingsEsc($csrf)?>"><?php foreach($schema as $id=>$section):?><section id="<?=settingsEsc($id)?>" class="card"><div class="cardhead"><div><h2><?=settingsEsc($section['title'])?></h2><p><?=settingsEsc($section['description'])?></p></div><span class="tag"><?=count($section['fields'])?> pól</span></div><div class="grid"><?php foreach($section['fields'] as $name=>$field):$secret=!empty($field['secret']);$isSet=projectSettingConfigured($name);$value=$secret?'':projectSetting($name);?><div class="field <?=!empty($field['multiline'])?'wide':''?>"><label for="<?=settingsEsc($name)?>"><?=settingsEsc($field['label'])?><?php if($secret&&$isSet):?><span class="secretstate">● ustawiono</span><?php endif?></label><?php if($secret):?><span class="hint">Puste pole zachowuje obecny sekret.<?php if(!$isSet):?> <span class="empty">Nie ustawiono.</span><?php endif?></span><?php endif?><?php if(!empty($field['multiline'])):?><textarea id="<?=settingsEsc($name)?>" name="<?=settingsEsc($name)?>" spellcheck="false" placeholder="Wklej klucz PEM"><?=settingsEsc($value)?></textarea><?php else:?><input id="<?=settingsEsc($name)?>" name="<?=settingsEsc($name)?>" type="<?=$secret?'password':(!empty($field['number'])?'number':'text')?>" value="<?=settingsEsc($value)?>" <?=!empty($field['number'])?'min="'.(int)$field['min'].'" max="'.(int)$field['max'].'" step="1"':''?> <?=$secret?'autocomplete="new-password"':''?>><?php endif?></div><?php endforeach?></div></section><?php endforeach?><div class="footer"><button class="save" type="submit">Zapisz ustawienia</button></div></form></div><p class="security">Sekrety są szyfrowane lokalnym kluczem serwera. Zrób kopię katalogu danych wraz z kluczem; bez niego zapisanych sekretów nie da się odczytać. Konfiguracja runnera i limity agentów zaczną działać po podłączeniu osobnego środowiska Codex.</p></main></body></html>
